        T* data() const { return static_cast<T*>(_data); }
        
        size_t rows() const { return _rows; }
        size_t cols() const { return _cols; }
        DCGArrayType type() const { return _type; }
        PyObject* pyobj() const { return _pyobj; }

        void ensure_double() {
            if (_type == DCG_DOUBLE) return;
            _convert_to_double();
        }
